// Assemble the digest request — backend endpoint returns all stats
msg.method = 'GET';
msg.url = process.env.LEADS_API_URL + '/api/command';
msg.headers = { 'X-Internal-Token': process.env.LEADS_INTERNAL_TOKEN || '' };
return msg;

const d = msg.payload || {};
const stats = d.stats || {};
const breakdown = d.state_breakdown || {};
const now = new Date().toLocaleString('en-US', { timeZone: 'America/New_York', dateStyle: 'full', timeStyle: 'short' });

const stateLines = Object.entries(breakdown).map(([st, s]) =>
  `  • *${st}* — ${s.total || 0} total · ${s.last_24h || 0} new · ${s.hot_leads || 0} hot`
).join('\n');

const text = [
  `*☘️ ShamrockLeads — Daily Ops Digest*`,
  `_${now}_`,
  ``,
  `*📊 Arrest Intelligence*`,
  `  • Total Records: *${(stats.total_arrests || 0).toLocaleString()}*`,
  `  • Last 24h: *${stats.arrests_24h || 0}*`,
  `  • Hot Leads: *${stats.hot_leads || 0}* 🔥  Warm: *${stats.warm_leads || 0}* 🟡`,
  `  • Bond-Ready: *${stats.bond_ready || 0}*`,
  ``,
  `*🗺 By State*`,
  stateLines || '  (no data)',
  ``,
  `*🏥 Scraper Fleet*`,
  `  • Active: *${stats.active_scrapers || '—'}*  Errors: *${stats.error_scrapers || 0}*`,
  ``,
  `_View full dashboard: https://leads.shamrockbailbonds.biz_`
].join('\n');

msg.payload = {
  channel: process.env.SLACK_OPS_CHANNEL || '#ops-daily',
  text: text,
  mrkdwn: true
};
msg.headers = { 'Authorization': 'Bearer ' + (process.env.SLACK_BOT_TOKEN || ''), 'Content-Type': 'application/json' };
return msg;

const ok = msg.payload && msg.payload.ok;
node.status({ fill: ok ? 'green' : 'red', shape: 'dot', text: ok ? 'sent ' + new Date().toLocaleTimeString() : 'error' });
node.log('Ops digest ' + (ok ? 'sent OK' : 'FAILED: ' + JSON.stringify(msg.payload)));
return null;

msg.method = 'GET';
msg.url = (process.env.LEADS_API_URL || 'http://localhost:8000') + '/api/scraper-health';
msg.headers = { 'X-Internal-Token': process.env.LEADS_INTERNAL_TOKEN || '' };
return msg;

const counties = (msg.payload && msg.payload.counties) || [];
const prev = global.get('scraperErrorCache') || {};
const newErrors = [];
const curr = {};

counties.forEach(c => {
  const key = (c.state || 'FL') + ':' + c.county;
  curr[key] = c.status;
  if (c.status === 'error' && prev[key] !== 'error') {
    newErrors.push({ county: c.county, state: c.state || 'FL', last_run: c.last_run, error: c.last_error || 'unknown error' });
  }
});

global.set('scraperErrorCache', curr);

if (newErrors.length === 0) {
  node.status({ fill: 'green', shape: 'dot', text: 'clean ' + new Date().toLocaleTimeString() });
  return null;
}

const lines = newErrors.map(e =>
  `  • *${e.county}* (${e.state}) — \`${String(e.error).slice(0, 80)}\``
).join('\n');

msg.payload = {
  channel: process.env.SLACK_SCRAPER_CHANNEL || '#scraper-alerts',
  text: `*🚨 Scraper Error Alert* — ${newErrors.length} new failure${newErrors.length > 1 ? 's' : ''}\n${lines}`,
  mrkdwn: true
};
msg.headers = { 'Authorization': 'Bearer ' + (process.env.SLACK_BOT_TOKEN || ''), 'Content-Type': 'application/json' };
node.status({ fill: 'red', shape: 'dot', text: newErrors.length + ' new errors' });
return msg;

// Query the re-arrest detection endpoint
msg.method = 'POST';
msg.url = (process.env.LEADS_API_URL || 'http://localhost:8000') + '/api/automation/trigger/rearrest_detection';
msg.headers = { 'X-Internal-Token': process.env.LEADS_INTERNAL_TOKEN || '', 'Content-Type': 'application/json' };
msg.payload = {};
return msg;

const ok = msg.payload && msg.payload.success;
node.status({ fill: ok ? 'green' : 'yellow', shape: 'dot', text: (ok ? 'triggered ' : 'warn ') + new Date().toLocaleTimeString() });
return null;

msg.method = 'POST';
msg.url = (process.env.LEADS_API_URL || 'http://localhost:8000') + '/api/automation/trigger/signnow_poller';
msg.headers = { 'X-Internal-Token': process.env.LEADS_INTERNAL_TOKEN || '', 'Content-Type': 'application/json' };
msg.payload = {};
return msg;

msg.method = 'POST';
msg.url = (process.env.LEADS_API_URL || 'http://localhost:8000') + '/api/automation/trigger/wix_sync';
msg.headers = { 'X-Internal-Token': process.env.LEADS_INTERNAL_TOKEN || '', 'Content-Type': 'application/json' };
msg.payload = {};
return msg;
